class ShipmentEvent(BaseModel):
    """
    A date and/or time event related to a shipment slot, such as ETA, loading, nomination, or
    completion.
    """

    model_config = ConfigDict(is_entity=False)

    event_type: ShipmentEventType = Field(
        ShipmentEventType.OTHER,
        description=(
            "LOOK FOR the column header for the event type (e.g., ETA, Loading Commencement, "
            "Nomination Received)."
        ),
        examples=["Date ETA of Ship", "Date Nomination Accepted"],
    )

    event_date: Optional[date] = Field(
        None,
        description=(
            "LOOK FOR the date value in the corresponding event column; use YYYY-MM-DD format."
        ),
        examples=["8/07/2026", "10/07/2026"],
    )

    event_time: Optional[str] = Field(
        None,
        description="LOOK FOR the time value in the corresponding event column.",
        examples=["8:45:00 AM", "3:05:00 PM"],
    )

    @field_validator("event_type", mode="before")
    @classmethod
    def _normalize_event_type(cls, v: Any) -> Any:
        """Map free-text values onto ShipmentEventType members (falls back to OTHER)."""
        return _normalize_enum(ShipmentEventType, v)

    def __str__(self) -> str:
        parts = [self.event_date, self.event_time]
        return " ".join(str(p) for p in parts if p) or "Unknown"


